'use client';

import { useState } from 'react';

const faqs = [
  {
    question: 'How do I get a free doctor opinion and cost quotation?',
    answer: 'Simply upload or share your recent medical reports, MRI/CT scans, and medical history with us via our web inquiry form or directly on WhatsApp. Within 24-48 hours, our super-specialist panel of chief surgeons at top Indian hospitals will review your case and provide an itemized treatment estimate and recommended surgical approach at zero cost.'
  },
  {
    question: 'How do I obtain an Indian Medical Visa (MED Visa) and Visa Invitation Letter (VIL)?',
    answer: 'Once you decide to proceed with the recommended treatment plan, we immediately issue an official Government-recognized Hospital Visa Invitation Letter (VIL) with the hospital seal and surgeon signature. You can submit this to your nearest Indian Embassy or apply for the Indian e-Medical Visa online, which is typically approved within 48 to 72 hours.'
  },
  {
    question: 'What is included in the treatment package cost? Are there any hidden fees?',
    answer: 'We believe in 100% transparent direct hospital pricing. The quoted package typically includes: surgeon fees, operating theater charges, standard implants/prosthesis (FDA-approved), pre-op diagnostics, standard hospital stay (private or semi-private room), nursing, routine medications, and post-op rehabilitation during the hospital stay. You pay the hospital directly with zero facilitator markup.'
  },
  {
    question: 'Can a family member or caregiver accompany me to India?',
    answer: 'Yes! The Indian government grants Medical Attendant Visas (MED-X) for up to two family members or companions. We arrange comfortable accommodation for your attendant right next to or inside the hospital premises, including kitchen-equipped sanitized serviced apartments or hotels based on your preference.'
  },
  {
    question: 'Will there be language or communication issues in India?',
    answer: 'Not at all. English is the primary language used by all doctors, medical specialists, and hospital staff in India. In addition, RUHM assigns a dedicated 1-on-1 multilingual coordinator and translator fluent in Arabic, Russian, French, Bengali, and Swahili to accompany you through all clinical consultations and hospital procedures.'
  },
  {
    question: 'What happens after I get discharged and return to my home country?',
    answer: 'Before your flight, the hospital provides a complete English discharge summary, post-care medication schedule, physiotherapy guidelines, and a "Fit to Fly" certificate. Once you are back home, RUHM coordinates ongoing lifelong telemedicine video calls with your treating chief surgeon to ensure complete recovery.'
  },
  {
    question: 'What payment modes are accepted by Indian hospitals?',
    answer: 'Hospitals accept international credit/debit cards (Visa, MasterCard, Amex), direct international swift wire transfers (TT), foreign currencies (USD, EUR, GBP) exchanged at authorized bank counters, and major international health insurance / TPA coverage (subject to prior clearance).'
  },
];

export default function FAQ() {
  const [openIndex, setOpenIndex] = useState<number | null>(0);

  const toggleFAQ = (index: number) => {
    setOpenIndex(openIndex === index ? null : index);
  };

  return (
    <section id="faq" className="py-20 bg-white relative">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">
        
        {/* Header */}
        <div className="text-center max-w-3xl mx-auto mb-16">
          <div className="inline-flex items-center gap-1.5 px-3.5 py-1 rounded-full bg-blue-100 text-blue-800 text-xs font-bold uppercase tracking-wider mb-3">
            ❓ COMMON QUESTIONS
          </div>
          <h2 className="text-3xl sm:text-4xl font-extrabold text-slate-900 tracking-tight">
            Frequently Asked Questions
          </h2>
          <p className="mt-4 text-base sm:text-lg text-slate-600">
            Everything you need to know about traveling to India for safe, affordable medical treatment.
          </p>
          <div className="w-16 h-1 bg-blue-600 mx-auto mt-4 rounded-full"></div>
        </div>

        {/* Accordion */}
        <div className="space-y-4">
          {faqs.map((faq, index) => {
            const isOpen = openIndex === index;
            return (
              <div
                key={index}
                className={`rounded-2xl border transition-all duration-200 overflow-hidden ${
                  isOpen
                    ? 'border-blue-500 bg-blue-50/20 shadow-md'
                    : 'border-slate-200 bg-slate-50 hover:border-slate-300'
                }`}
              >
                <button
                  onClick={() => toggleFAQ(index)}
                  className="w-full px-6 py-5 text-left font-bold text-slate-900 hover:text-blue-600 transition flex justify-between items-center gap-4 text-sm sm:text-base focus:outline-none"
                >
                  <span className="flex items-center gap-3">
                    <span className={`w-7 h-7 rounded-lg flex items-center justify-center text-xs font-extrabold flex-shrink-0 transition-colors ${
                      isOpen ? 'bg-blue-600 text-white' : 'bg-slate-200 text-slate-700'
                    }`}>
                      Q{index + 1}
                    </span>
                    <span>{faq.question}</span>
                  </span>
                  <span
                    className={`w-8 h-8 rounded-full flex items-center justify-center bg-white border border-slate-200 text-slate-600 flex-shrink-0 transition-transform duration-200 ${
                      isOpen ? 'rotate-180 bg-blue-600 text-white border-blue-600' : ''
                    }`}
                  >
                    ▼
                  </span>
                </button>

                {isOpen && (
                  <div className="px-6 pb-6 pt-1 text-xs sm:text-sm text-slate-600 leading-relaxed border-t border-blue-100/60 mt-1">
                    {faq.answer}
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* Still have questions */}
        <div className="mt-12 text-center bg-slate-100 p-6 rounded-2xl border border-slate-200">
          <p className="text-slate-700 text-sm font-medium">
            Have a question that is not listed here?{' '}
            <a
              href="https://wa.me/919654250311?text=Hi%2C%20I%20have%20a%20specific%20question%20regarding%20medical%20travel"
              target="_blank"
              rel="noopener noreferrer"
              className="text-blue-600 hover:text-blue-800 font-bold underline ml-1"
            >
              Ask our Medical Counselor on WhatsApp →
            </a>
          </p>
        </div>

      </div>
    </section>
  );
}

